// src/components/Products.js
import React, { useEffect, useRef, useState } from 'react';
import './Product.css';

const partners = [
  { name: 'Partner A', logo: 'https://via.placeholder.com/150x80?text=Partner+A' },
  { name: 'Partner B', logo: 'https://via.placeholder.com/150x80?text=Partner+B' },
];

const products = [
  {
    name: 'Smart Thermostat',
    image: 'https://via.placeholder.com/300x200?text=Thermostat',
    description: "Control your home temperature remotely with smart scheduling and AI.",
  },
  {
    name: 'Smart Switch',
    image: 'https://via.placeholder.com/300x200?text=Smart+Switch',
    description: "Turn devices on/off from anywhere, with automation support.",
  },
  {
    name: 'Smart Sensor',
    image: 'https://via.placeholder.com/300x200?text=Sensor',
    category: 'Security',
  },
  {
    name: 'Smart Lighting',
    image: 'https://via.placeholder.com/300x200?text=Lighting',
    category: 'Lighting',
  },
  {
    name: 'Smart Speaker',
    image: 'https://via.placeholder.com/300x200?text=Speaker',
    category: 'Audio',
  },
  {
    name: 'KNX Integration Driver',
    image: 'https://via.placeholder.com/300x200?text=KNX+Driver',
    category: 'Integration',
  },
  {
    name: 'DALI Driver',
    image: 'https://via.placeholder.com/300x200?text=DALI+Driver',
    category: 'Integration',
  },
  {
    name: 'Automated Curtain System',
    image: 'https://via.placeholder.com/300x200?text=Curtains',
    category: 'Window Control',
  },
  {
    name: 'Music System Integration',
    image: 'https://via.placeholder.com/300x200?text=Music+System',
    category: 'Audio',
  },
  {
    name: 'Office Automation Hub',
    image: 'https://via.placeholder.com/300x200?text=Office+Hub',
    category: 'Automation',
  },
];

function Products() {
  const [isVisible, setIsVisible] = useState(false);
  const sectionRef = useRef(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      entries => {
        if (entries[0].isIntersecting) {
          setIsVisible(true);
          observer.disconnect();
        }
      },
      { threshold: 0.2 }
    );

    if (sectionRef.current) observer.observe(sectionRef.current);

    return () => observer.disconnect();
  }, []);

  return (
    <section ref={sectionRef} className={`products-section ${isVisible ? 'visible' : ''}`}>
      <div className="partners-section">
        <h2>Partners</h2>
        <div className="partners-logos">
          {partners.map((partner, index) => (
            <div className="partner-card" key={index}>
              <img src={partner.logo} alt={partner.name} />
            </div>
          ))}
        </div>
      </div>

      <h2>Our Products</h2>
      <div className="product-grid">
        {products.map((product, index) => (
          <div className="product-card" key={index}>
            <img src={product.image} alt={product.name} />
            <h3>{product.name}</h3>
            <p className="category">{product.category}</p>
          </div>
        ))}
      </div>
    </section>
  );
}

export default Products;
